/**
 * Public reference IDs (TSK21ID2489, LD07ID5316, HW-T16ID24 ...) are generated by the database (gen_ref(), column default)
 * and protected by a unique index. On the rare chance that two rows roll the same ID, the insert is simply retried
 * and the database rolls a fresh one.
 */
export async function withRefRetry<T>(insert: () => Promise<T>, attempts = 8): Promise<T> {
  for (let i = 1; ; i++) {
    try { return await insert(); }
    catch (e: any) {
      const clash = e?.code === '23505' && /task_no|lead_no|ticket_no/.test(String(e?.constraint || e?.detail || ''));
      if (!clash || i >= attempts) throw e;
    }
  }
}
